1	import React, {
2	  useCallback,
3	  useEffect,
4	  useMemo,
5	  useRef,
6	  useState,
7	} from "react";
8	import {
9	  Menu,
10	  MenuItem,
11	  Popover,
12	  Position,
13	  Button,
14	  InputGroup,
15	  Intent,
16	} from "@blueprintjs/core";
17	import ReactDOM from "react-dom";
18	import getUids from "roamjs-components/dom/getUids";
19	import getTextByBlockUid from "roamjs-components/queries/getTextByBlockUid";
20	import updateBlock from "roamjs-components/writes/updateBlock";
21	import posthog from "posthog-js";
22	import { getCoordsFromTextarea } from "roamjs-components/components/CursorMenu";
23	import { OnloadArgs } from "roamjs-components/types";
24	import getDiscourseNodes, { DiscourseNode } from "~/utils/getDiscourseNodes";
25	import {
26	  DISCOURSE_NODE_MIN_SEARCH_SCORE,
27	  DISCOURSE_NODE_MINI_SEARCH_OPTIONS,
28	  getPulledDiscourseNodeTitle,
29	  getPulledDiscourseNodeUid,
30	  queryDiscourseNodesByFormatSync,
31	} from "~/utils/discourseNodeSearch";
32	import { Result } from "~/utils/types";
33	import MiniSearch from "minisearch";
34	import { setPersonalSetting } from "~/components/settings/utils/accessors";
35	import { PERSONAL_KEYS } from "~/components/settings/utils/settingKeys";
36	
37	type Props = {
38	  textarea: HTMLTextAreaElement;
39	  triggerPosition: number;
40	  onClose: () => void;
41	  triggerText: string;
42	};
43	
44	type MinisearchResult = Result & {
45	  type: string;
46	};
47	
48	const MAX_ITEMS_PER_TYPE = 10;
49	
50	const waitForBlock = ({
51	  uid,
52	  text,
53	  retries = 0,
54	  maxRetries = 30,
55	}: {
56	  uid: string;
57	  text: string;
58	  retries?: number;
59	  maxRetries?: number;
60	}): Promise<void> =>
61	  getTextByBlockUid(uid) === text
62	    ? Promise.resolve()
63	    : retries >= maxRetries
64	      ? Promise.resolve()
65	      : new Promise((resolve) =>
66	          setTimeout(
67	            () =>
68	              resolve(
69	                waitForBlock({
70	                  uid,
71	                  text,
72	                  retries: retries + 1,
73	                  maxRetries,
74	                }),
75	              ),
76	            10,
77	          ),
78	        );
79	
80	const NodeSearchMenu = ({
81	  onClose,
82	  textarea,
83	  triggerPosition,
84	  triggerText,
85	}: { onClose: () => void } & Props) => {
86	  const MENU_WIDTH = 400;
87	  const [activeIndex, setActiveIndex] = useState(0);
88	  const [searchTerm, setSearchTerm] = useState("");
89	  const [discourseTypes, setDiscourseTypes] = useState<DiscourseNode[]>([]);
90	  const [checkedTypes, setCheckedTypes] = useState<Record<string, boolean>>({});
91	  const [isLoading, setIsLoading] = useState(true);
92	  const [searchResults, setSearchResults] = useState<Record<string, Result[]>>(
93	    {},
94	  );
95	  const [isFilterMenuVisible, setIsFilterMenuVisible] = useState(false);
96	  const typeIds = useMemo(
97	    () => discourseTypes.map((t) => t.type),
98	    [discourseTypes],
99	  );
100	  const isAllSelected = useMemo(
101	    () => typeIds.length > 0 && typeIds.every((id) => !!checkedTypes[id]),
102	    [typeIds, checkedTypes],
103	  );
104	  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
105	  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
106	  const miniSearchRef = useRef<MiniSearch<MinisearchResult> | null>(null);
107	  const POPOVER_TOP_OFFSET = 30;
108	
109	  const debouncedSearchTerm = useCallback((term: string) => {
110	    if (searchTimeoutRef.current) {
111	      clearTimeout(searchTimeoutRef.current);
112	    }
113	
114	    searchTimeoutRef.current = setTimeout(() => {
115	      setSearchTerm(term);
116	    }, 300);
117	  }, []);
118	
119	  const searchNodesForType = (node: DiscourseNode): Result[] => {
120	    const results: Result[] = [];
121	
122	    queryDiscourseNodesByFormatSync({ node }).forEach((result) => {
123	      const uid = getPulledDiscourseNodeUid(result);
124	      const text = getPulledDiscourseNodeTitle(result);
125	      if (!uid || !text) return;
126	
127	      results.push({ id: uid, text, uid } as Result);
128	    });
129	
130	    return results;
131	  };
132	
133	  const searchWithMiniSearch = useCallback(
134	    (searchTerm: string, typeFilter?: string[]): Record<string, Result[]> => {
135	      if (!miniSearchRef.current) {
136	        return {};
137	      }
138	
139	      const search = miniSearchRef.current;
140	
141	      if (!searchTerm.trim()) {
142	        if (!typeFilter) {
143	          return {};
144	        }
145	
146	        const allResults: Record<string, Result[]> = {};
147	        typeFilter.forEach((type) => {
148	          const results = (
149	            search.search(MiniSearch.wildcard, {
150	              filter: (result) =>
151	                (result as unknown as MinisearchResult).type === type,
152	            }) as unknown as MinisearchResult[]
153	          )
154	            .slice(0, MAX_ITEMS_PER_TYPE)
155	            .map((r) => ({
156	              text: r.text,
157	              uid: r.uid,
158	            }));
159	          allResults[type] = results;
160	        });
161	
162	        return allResults;
163	      }
164	
165	      const rawSearchResults = search.search(searchTerm, {
166	        fields: ["text"],
167	        ...DISCOURSE_NODE_MINI_SEARCH_OPTIONS,
168	        filter: typeFilter
169	          ? (result) =>
170	              typeFilter.includes((result as unknown as MinisearchResult).type)
171	          : undefined,
172	      });
173	
174	      const filteredResults = rawSearchResults.filter(
175	        (r) => r.score > DISCOURSE_NODE_MIN_SEARCH_SCORE,
176	      );
177	
178	      const searchResults = (
179	        filteredResults as unknown as MinisearchResult[]
180	      ).map((r) => ({
181	        text: r.text,
182	        uid: r.uid,
183	        type: r.type,
184	      }));
185	
186	      const results = searchResults.reduce(
187	        (acc, result) => {
188	          if (!acc[result.type]) {
189	            acc[result.type] = [];
190	          }
191	          if (acc[result.type].length < MAX_ITEMS_PER_TYPE) {
192	            acc[result.type].push({
193	              id: result.uid,
194	              text: result.text,
195	              uid: result.uid,
196	            });
197	          }
198	          return acc;
199	        },
200	        {} as Record<string, Result[]>,
201	      );
202	
203	      return results;
204	    },
205	    [],
206	  );
207	
208	  useEffect(() => {
209	    const fetchNodeTypes = () => {
210	      setIsLoading(true);
211	
212	      const allNodeTypes = getDiscourseNodes().filter(
213	        (n) => n.backedBy === "user",
214	      );
215	
216	      setDiscourseTypes(allNodeTypes);
217	
218	      const initialCheckedTypes: Record<string, boolean> = {};
219	      allNodeTypes.forEach((t) => {
220	        initialCheckedTypes[t.type] = true;
221	      });
222	      setCheckedTypes(initialCheckedTypes);
223	
224	      const allNodesCache: Record<string, Result[]> = {};
225	      allNodeTypes.forEach((type) => {
226	        allNodesCache[type.type] = searchNodesForType(type);
227	      });
228	
229	      const miniSearch = new MiniSearch<MinisearchResult>({
230	        fields: ["text"],
231	        storeFields: ["text", "uid", "type"],
232	        idField: "uid",
233	      });
234	
235	      const documentsToIndex: MinisearchResult[] = [];
236	      const seenUids = new Set<string>();
237	
238	      allNodeTypes.forEach((type) => {
239	        const nodes = allNodesCache[type.type] || [];
240	        nodes.forEach((node) => {
241	          if (seenUids.has(node.uid)) return;
242	          seenUids.add(node.uid);
243	          documentsToIndex.push({
244	            ...node,
245	            type: type.type,
246	          });
247	        });
248	      });
249	
250	      miniSearch.addAll(documentsToIndex);
251	      miniSearchRef.current = miniSearch;
252	
253	      const initialSearchResults = Object.fromEntries(
254	        allNodeTypes.map((type) => [type.type, []]),
255	      );
256	      setSearchResults(initialSearchResults);
257	
258	      setIsLoading(false);
259	    };
260	
261	    fetchNodeTypes();
262	  }, []);
263	
264	  useEffect(() => {
265	    if (isLoading || !miniSearchRef.current) return;
266	
267	    const selectedTypes = discourseTypes
268	      .filter((type) => checkedTypes[type.type])
269	      .map((type) => type.type);
270	
271	    const newResults = searchWithMiniSearch(searchTerm, selectedTypes);
272	    setSearchResults(newResults);
273	  }, [
274	    searchTerm,
275	    isLoading,
276	    discourseTypes,
277	    checkedTypes,
278	    searchWithMiniSearch,
279	  ]);
280	
281	  const menuRef = useRef<HTMLUListElement>(null);
282	  const { ["block-uid"]: blockUid, ["window-id"]: windowId } = useMemo(
283	    () =>
284	      window.roamAlphaAPI.ui.getFocusedBlock() || {
285	        "block-uid": "",
286	        "window-id": "",
287	      },
288	    [],
289	  );
290	
291	  const filteredTypes = useMemo(() => {
292	    return discourseTypes
293	      .filter((type) => checkedTypes[type.type])
294	      .filter((type) => searchResults[type.type]?.length > 0);
295	  }, [discourseTypes, checkedTypes, searchResults]);
296	
297	  const allItems = useMemo(() => {
298	    const items: {
299	      typeIndex: number;
300	      itemIndex: number;
301	      item: Result;
302	    }[] = [];
303	
304	    filteredTypes.forEach((type, typeIndex) => {
305	      const typeResults = searchResults[type.type] || [];
306	      typeResults.forEach((item, itemIndex) => {
307	        items.push({ typeIndex, itemIndex, item });
308	      });
309	    });
310	
311	    return items;
312	  }, [filteredTypes, searchResults]);
313	
314	  const onSelect = useCallback(
315	    (item: Result) => {
316	      if (!blockUid) {
317	        onClose();
318	        return;
319	      }
320	      void waitForBlock({ uid: blockUid, text: textarea.value })
321	        .then(() => {
322	          onClose();
323	
324	          setTimeout(() => {
325	            const originalText = getTextByBlockUid(blockUid);
326	
327	            const prefix = originalText.substring(0, triggerPosition);
328	            const suffix = originalText.substring(textarea.selectionStart);
329	            const pageRef = `[[${item.text}]]`;
330	
331	            const newText = `${prefix}${pageRef}${suffix}`;
332	            void updateBlock({ uid: blockUid, text: newText }).then(() => {
333	              const newCursorPosition = triggerPosition + pageRef.length;
334	
335	              if (window.roamAlphaAPI.ui.setBlockFocusAndSelection) {
336	                void window.roamAlphaAPI.ui.setBlockFocusAndSelection({
337	                  location: {
338	                    "block-uid": blockUid,
339	                    "window-id": windowId,
340	                  },
341	                  selection: { start: newCursorPosition },
342	                });
343	              } else {
344	                setTimeout(() => {
345	                  const textareaElements =
346	                    document.querySelectorAll("textarea");
347	                  for (const el of textareaElements) {
348	                    if (getUids(el).blockUid === blockUid) {
349	                      el.focus();
350	                      el.setSelectionRange(
351	                        newCursorPosition,
352	                        newCursorPosition,
353	                      );
354	                      break;
355	                    }
356	                  }
357	                }, 50);
358	              }
359	            });
360	            posthog.capture("Discourse Node: Selected from Search Menu", {
361	              id: item.id,
362	              text: item.text,
363	            });
364	          }, 10);
365	        })
366	        .catch((error) => {
367	          console.error("Error waiting for block:", error);
368	        });
369	    },
370	    [blockUid, onClose, textarea, triggerPosition, windowId],
371	  );
372	
373	  const handleTextAreaInput = useCallback(() => {
374	    const triggerRegex = new RegExp(
375	      `${triggerText.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(.*)$`,
376	    );
377	    const textBeforeCursor = textarea.value.substring(
378	      triggerPosition,
379	      textarea.selectionStart,
380	    );
381	    const match = triggerRegex.exec(textBeforeCursor);
382	    if (match) {
383	      debouncedSearchTerm(match[1]);
384	    } else {
385	      onClose();
386	      return;
387	    }
388	  }, [textarea, onClose, debouncedSearchTerm, triggerPosition, triggerText]);
389	
390	  const keydownListener = useCallback(
391	    (e: KeyboardEvent) => {
392	      if (e.key === "ArrowDown" && allItems.length) {
393	        setActiveIndex((prev) => (prev + 1) % allItems.length);
394	        e.preventDefault();
395	        e.stopPropagation();
396	      } else if (e.key === "ArrowUp" && allItems.length) {
397	        setActiveIndex(
398	          (prev) => (prev - 1 + allItems.length) % allItems.length,
399	        );
400	        e.preventDefault();
401	        e.stopPropagation();
402	      } else if (e.key === "Enter") {
403	        if (allItems.length > 0) {
404	          e.preventDefault();
405	          e.stopPropagation();
406	          onSelect(allItems[activeIndex].item);
407	        }
408	      } else if (e.key === "Escape") {
409	        onClose();
410	        e.preventDefault();
411	        e.stopPropagation();
412	      }
413	    },
414	    [allItems, activeIndex, setActiveIndex, onSelect, onClose],
415	  );
416	
417	  useEffect(() => {
418	    if (activeIndex >= allItems.length) {
419	      setActiveIndex(0);
420	    }
421	  }, [allItems, activeIndex]);
422	
423	  useEffect(() => {
424	    const listeningEl = textarea.closest(".rm-reference-item")
425	      ? textarea.parentElement
426	      : textarea;
427	
428	    if (listeningEl) {
429	      listeningEl.addEventListener("keydown", keydownListener);
430	      listeningEl.addEventListener("input", handleTextAreaInput);
431	    }
432	
433	    return () => {
434	      if (listeningEl) {
435	        listeningEl.removeEventListener("keydown", keydownListener);
436	        listeningEl.removeEventListener("input", handleTextAreaInput);
437	      }
438	    };
439	  }, [textarea, keydownListener, handleTextAreaInput]);
440	
441	  useEffect(() => {
442	    setTimeout(() => {
443	      handleTextAreaInput();
444	    }, 50);
445	  }, [handleTextAreaInput]);
446	
447	  useEffect(() => {
448	    return () => {
449	      if (searchTimeoutRef.current) {
450	        clearTimeout(searchTimeoutRef.current);
451	      }
452	    };
453	  }, []);
454	
455	  useEffect(() => {
456	    if (scrollContainerRef.current) {
457	      const activeItem = scrollContainerRef.current.querySelector(
458	        '[data-active="true"]',
459	      ) as HTMLElement;
460	
461	      if (activeItem) {
462	        const container = scrollContainerRef.current;
463	        const containerRect = container.getBoundingClientRect();
464	        const itemRect = activeItem.getBoundingClientRect();
465	
466	        if (
467	          itemRect.bottom > containerRect.bottom ||
468	          itemRect.top < containerRect.top
469	        ) {
470	          activeItem.scrollIntoView({
471	            block: "nearest",
472	            behavior: "auto",
473	          });
474	        }
475	      }
476	    }
477	  }, [activeIndex]);
478	
479	  let currentGlobalIndex = -1;
480	
481	  const handleTypeCheckChange = useCallback((typeKey: string) => {
482	    setCheckedTypes((prev) => ({
483	      ...prev,
484	      [typeKey]: !prev[typeKey],
485	    }));
486	  }, []);
487	
488	  const handleToggleAll = useCallback(
489	    (checked: boolean) => {
490	      setCheckedTypes(Object.fromEntries(typeIds.map((id) => [id, checked])));
491	    },
492	    [typeIds],
493	  );
494	
495	  const handleSelectOnly = useCallback(
496	    (node: DiscourseNode) => {
497	      const next = Object.fromEntries(
498	        typeIds.map((id) => [id, id === node.type]),
499	      );
500	      setCheckedTypes(next as Record<string, boolean>);
501	    },
502	    [typeIds],
503	  );
504	
505	  const renderTypeItem = useCallback(
506	    (item: DiscourseNode) => {
507	      const isSelected = !!checkedTypes[item.type];
508	      return (
509	        <MenuItem
510	          key={item.type}
511	          className="group !p-0"
512	          text={
513	            <div className="flex w-full items-center justify-between">
514	              <div className="flex flex-1 items-center px-2 py-1.5">
515	                <span className="mr-2">{isSelected ? "✓" : " "}</span>
516	                <span>{item.text}</span>
517	              </div>
518	              <Button
519	                minimal
520	                small
521	                className="flex !h-full items-center justify-center !rounded-none px-3 opacity-0 transition-opacity group-hover:opacity-100"
522	                onClick={(e) => {
523	                  e.stopPropagation();
524	                  handleSelectOnly(item);
525	                  setIsFilterMenuVisible(false);
526	                }}
527	                onMouseDown={(e) => e.preventDefault()}
528	              >
529	                Only
530	              </Button>
531	            </div>
532	          }
533	          icon={null}
534	          shouldDismissPopover={false}
535	          onClick={(e) => {
536	            e.preventDefault();
537	            e.stopPropagation();
538	            handleTypeCheckChange(item.type);
539	          }}
540	          onMouseDown={(e) => e.preventDefault()}
541	        />
542	      );
543	    },
544	    [checkedTypes, handleTypeCheckChange, handleSelectOnly],
545	  );
546	
547	  return (
548	    <Popover
549	      onClose={onClose}
550	      isOpen={true}
551	      canEscapeKeyClose
552	      minimal
553	      usePortal={true}
554	      target={<span />}
555	      position={Position.BOTTOM_LEFT}
556	      modifiers={{
557	        flip: { enabled: true },
558	        preventOverflow: { enabled: true, boundariesElement: "viewport" },
559	        offset: {
560	          enabled: true,
561	          fn: (data) => {
562	            if (data.placement?.startsWith("top") && data.offsets?.popper) {
563	              data.offsets.popper.top -= POPOVER_TOP_OFFSET;
564	            }
565	            return data;
566	          },
567	        },
568	      }}
569	      autoFocus={false}
570	      content={
571	        <div
572	          className="discourse-node-search-menu"
573	          style={{ width: MENU_WIDTH }}
574	        >
575	          {isLoading ? (
576	            <div className="p-3 text-center text-gray-500">Loading...</div>
577	          ) : (
578	            <>
579	              <div
580	                className="discourse-node-search-menu"
581	                style={{ width: MENU_WIDTH }}
582	              >
583	                <div className="flex items-center justify-between border-b border-gray-200 p-2">
584	                  <Button
585	                    icon="filter"
586	                    minimal
587	                    small
588	                    title="Filter by type"
589	                    onClick={(e) => {
590	                      e.stopPropagation();
591	                      e.preventDefault();
592	                      setIsFilterMenuVisible(!isFilterMenuVisible);
593	                    }}
594	                    onMouseDown={(e) => e.preventDefault()}
595	                  />
596	                </div>
597	                {isFilterMenuVisible && (
598	                  <div>
599	                    <div className="flex items-center justify-between px-3 py-2">
600	                      <span className="text-sm font-medium text-gray-700">
601	                        Filter by Type
602	                      </span>
603	                      <Button
604	                        small
605	                        intent={isAllSelected ? Intent.SUCCESS : Intent.PRIMARY}
606	                        icon={isAllSelected ? "tick" : "multi-select"}
607	                        onMouseDown={(e) => e.preventDefault()}
608	                        onClick={(e) => {
609	                          e.stopPropagation();
610	                          e.preventDefault();
611	                          handleToggleAll(!isAllSelected);
612	                        }}
613	                      >
614	                        {isAllSelected ? "All selected" : "Select all"}
615	                      </Button>
