import { getDiscourseNodeFormatExpression } from "@repo/database/lib/getDiscourseNodeFormatExpression";

export const DISCOURSE_NODE_MIN_SEARCH_SCORE = 0.1;

export const DISCOURSE_NODE_MINI_SEARCH_OPTIONS = {
  fuzzy: 0.2,
